try {
  final response = await http.get(url).timeout(Duration(seconds: 5));
} on TimeoutException catch (_) {
  print('Request timed out');
} on SocketException catch (_) {
  print('No internet connection');
} catch (e) {
  print('Unexpected error: $e');
}

